package api

import (
	"errors"
	"net/http"

	"example.com/shop/internal/orders"
)

// Orders serves the order endpoints.
type Orders struct {
	Store *orders.Store
}

// Get returns one order.
func (h Orders) Get(w http.ResponseWriter, r *http.Request) {
	o, err := h.Store.Order(r.Context(), r.PathValue("id"))
	switch {
	case errors.Is(err, orders.ErrNotFound):
		http.Error(w, "not found", http.StatusNotFound)
		return
	case err != nil:
		http.Error(w, "store", http.StatusInternalServerError)
		return
	}
	writeJSON(w, o)
}

// Cancel cancels an open order. The store refuses an order that is no longer
// open with ErrNotCancellable.
func (h Orders) Cancel(w http.ResponseWriter, r *http.Request) {
	err := h.Store.Cancel(r.Context(), r.PathValue("id"))
	switch {
	case errors.Is(err, orders.ErrNotFound):
		http.Error(w, "not found", http.StatusNotFound)
	case errors.Is(err, orders.ErrNotCancellable):
		http.Error(w, "order is no longer open", http.StatusConflict)
	case err != nil:
		http.Error(w, "store", http.StatusInternalServerError)
	default:
		w.WriteHeader(http.StatusNoContent)
	}
}
